parameters.jsCode:
const article = $('Validate Article').first().json;
const claude = $input.first().json;
const input = claude?.content?.[0]?.input ?? {};

const textItems = Array.isArray(input.text_feedback) ? input.text_feedback : [];
const imageFb = input.image_feedback?.comment ? input.image_feedback : null;

const rows = [];

for (const item of textItems) {
  if (!item?.comment) continue;
  rows.push({
    slot_id: article.slot_id,
    article_id: article.article_id,
    feedback_type: 'text',
    reviewer_name: 'Hoofdredacteur',
    comment: String(item.comment).trim(),
    action_label: item.action_label ? String(item.action_label) : 'Remove',
    excerpt: item.excerpt ? String(item.excerpt) : null,
  });
}

if (imageFb) {
  rows.push({
    slot_id: article.slot_id,
    article_id: article.article_id,
    feedback_type: 'image',
    reviewer_name: 'Hoofdredacteur',
    comment: String(imageFb.comment).trim(),
    action_label: imageFb.action_label ? String(imageFb.action_label) : 'New image',
    excerpt: null,
  });
}

if (rows.length === 0) {
  rows.push({
    slot_id: article.slot_id,
    article_id: article.article_id,
    feedback_type: 'text',
    reviewer_name: 'Hoofdredacteur',
    comment: String(input.summary || 'Geen specifieke feedback.'),
    action_label: null,
    excerpt: null,
  });
}

return rows.map((row) => ({ json: row }));
